import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const m=JSON.parse('{"title":"Week 8 Homework — Project 1 final","description":"","frontmatter":{"source":"weeks/08-own-it/homework.md"},"headers":[],"relativePath":"weeks/08-own-it/homework.md","filePath":"weeks/08-own-it/homework.md"}'),n={name:"weeks/08-own-it/homework.md"};function s(i,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-8-homework--project-1-final" tabindex="-1">Week 8 Homework — Project 1 final <a class="header-anchor" href="#week-8-homework--project-1-final" aria-label="Permalink to &quot;Week 8 Homework — Project 1 final&quot;">​</a></h1><p><strong>Due before next week&#39;s Studio A</strong> (week 9; default 11:59 pm the night before) · <strong>Core:</strong> about 5½ hours, including project time, required · <strong>Stretch:</strong> optional</p><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><p>In your <strong>public Project 1 repository</strong>:</p><ul><li>☐ Every MUST criterion passes on your GitHub Pages site (or was moved to SHOULD, with the reason in your README&#39;s &quot;Known issues&quot;)</li><li>☐ Plain <code>index.html</code>, <code>style.css</code>, <code>app.js</code> and <code>lib/</code> modules: no frameworks, no build step, no npm packages</li><li>☐ <strong>At least three automated tests</strong> of your pure logic passing with <code>npm test</code>, each seen failing once, output in <code>TESTS.md</code></li><li>☐ <code>TESTS.md</code>: a manual test for every criterion, <strong>at least 3 edge-case tests</strong>, results dated, &quot;Bugs found by testing&quot; with commits</li><li>☐ <code>SPEC.md</code> up to date, including the criterion for the function you wrote by hand</li><li>☐ <code>README.md</code>: live link, &quot;How it works&quot;, acceptance table, known issues, credits</li><li>☐ <code>PROMPTS.md</code> covering weeks 5–8 (details in task 6)</li><li>☐ At least 6 small commits with clear messages, including at least one <code>git revert</code></li><li>☐ No real personal data about other people, and no classmates&#39; names, anywhere in the repository</li></ul><p>On <strong>Canvas</strong> (private: never in your repository):</p><ul><li>☐ Your week 8 reflection, written without AI, and the anonymous <strong>mid-course survey</strong></li><li>☐ Your repository link and your GitHub Pages link</li></ul><p>Also: <strong>oral walkthrough 1</strong> done, in a studio or office hours (you can retake it once within 7 days), and codespaces stopped.</p><h2 id="time-plan" tabindex="-1">Time plan <a class="header-anchor" href="#time-plan" aria-label="Permalink to &quot;Time plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Kind</th><th>Time</th></tr></thead><tbody><tr><td>1. Make every MUST criterion pass</td><td>Project time</td><td>about 2 h</td></tr><tr><td>2. Finish your automated tests</td><td>Homework</td><td>1 h</td></tr><tr><td>3. Finish <code>TESTS.md</code></td><td>Homework</td><td>45 min</td></tr><tr><td>4. Finish your README</td><td>Homework</td><td>30 min</td></tr><tr><td>5. Walkthrough 1, if not done in a studio</td><td>Homework</td><td>15 min</td></tr><tr><td>6. Update <code>SPEC.md</code> and <code>PROMPTS.md</code></td><td>Journal</td><td>30 min</td></tr><tr><td>7. Reflection on Canvas</td><td>Journal</td><td>30 min</td></tr><tr><td>8. Mid-course survey</td><td>Homework</td><td>10 min</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>about 5½ h</strong></td></tr></tbody></table><p>Before next week&#39;s Studio A, also do the &quot;Before Studio A&quot; list on the <a href="./../09-apis-and-secrets/">week 9 page</a>.</p><p>This is the finish line for <strong>Project 1</strong> (<a href="./../../projects/project-1-useful-tool.html">brief</a>, <a href="./../../assessment/rubrics.html#project-1">rubric</a>). 🟢 AI on for fixing: Copilot&#39;s <strong>Ask</strong> mode or your chat assistant, no agent mode yet (week 11). Use <a href="./../../resources/safe-loop.html">the Safe Loop</a> for every change: <strong>check first</strong>, one step, test, read the diff, <strong>teach back</strong>, commit.</p><hr><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><h3 id="1-make-every-must-criterion-pass-about-2-hours" tabindex="-1">1. Make every MUST criterion pass (about 2 hours) <a class="header-anchor" href="#1-make-every-must-criterion-pass-about-2-hours" aria-label="Permalink to &quot;1. Make every MUST criterion pass (about 2 hours)&quot;">​</a></h3><p>Carry on from last week&#39;s list, the same way: check first, fix, test, read the diff, teach back, commit. If you change a criterion instead of the code, change <code>SPEC.md</code> and say why in the commit message.</p><p>✅ <strong>Checkpoint:</strong> every MUST criterion passes <strong>on your GitHub Pages site</strong>, not only in the Codespace preview. Test it on your phone too.</p><h3 id="2-finish-your-automated-tests-1-hour" tabindex="-1">2. Finish your automated tests (1 hour) <a class="header-anchor" href="#2-finish-your-automated-tests-1-hour" aria-label="Permalink to &quot;2. Finish your automated tests (1 hour)&quot;">​</a></h3><ol><li>Finish <a href="./lab.html#part-a2--test-your-project-1-logic-25-min">lab Part A2</a> if needed: at least three tests (normal, boundary, empty), each seen failing once.</li><li><strong>Write one more test first,</strong> for an input your app should handle, before you look at whether the function handles it: accents or emoji (<code>&quot;Café ☕&quot;</code>), a number typed as text (<code>&quot;42&quot;</code>), a tab on its own (<code>&quot;\\t&quot;</code>). Predict the result, run <code>npm test</code>, and write in <code>PROMPTS.md</code> whether you were right. If it fails, decide yourself whether the function or the test is wrong, and say why.</li><li>Paste the summary lines of <code>npm test</code> (the <code>pass</code> and <code>fail</code> counts) into <code>TESTS.md</code>, and commit.</li></ol><p>Never change a test just to make it pass.</p><h3 id="3-finish-testsmd-45-min" tabindex="-1">3. Finish TESTS.md (45 min) <a class="header-anchor" href="#3-finish-testsmd-45-min" aria-label="Permalink to &quot;3. Finish TESTS.md (45 min)&quot;">​</a></h3><p>Complete last week&#39;s <code>TESTS.md</code>: a manual test for every criterion (including your hand-written function&#39;s), at least three edge cases marked &quot;(edge case)&quot;, the <strong>Automated tests</strong> table, and every test run <strong>on your live site</strong> with the date. Fill in <strong>Bugs found by testing</strong> with the commit that fixed each one. Anything you can&#39;t fix goes into &quot;Known issues&quot;: an honest known issue never costs points.</p><h3 id="4-finish-your-readme-30-min" tabindex="-1">4. Finish your README (30 min) <a class="header-anchor" href="#4-finish-your-readme-30-min" aria-label="Permalink to &quot;4. Finish your README (30 min)&quot;">​</a></h3><p>Your README (from the <a href="./../../templates/PROJECT_README.html">Project README template</a>) needs:</p><ul><li>The <strong>live link</strong> and, if you like, a screenshot.</li><li><strong>How it works:</strong> the 3–6 sentences you drafted last week, in your own words (you&#39;ll explain them out loud), plus the table: which file does what (including <code>lib/</code> and <code>tests/</code>), what is saved in localStorage and in what format (for example, &quot;a JSON array of plants under the key <code>plants</code>&quot;), and &quot;Authorization: n/a, single-user app; data stays in your browser&quot;.</li><li><strong>Run it yourself:</strong> &quot;Open the live site. To run it in a Codespace: <code>python3 -m http.server 8000</code> and open the forwarded port. To run the tests: <code>npm test</code>.&quot;</li><li><strong>Status against the spec:</strong> every criterion, marked ✅ passes or ⚠️ partly, with a note for anything that doesn&#39;t fully pass.</li><li><strong>Known issues and next steps</strong>, and <strong>Credits</strong> for anything you used from other people.</li></ul><h3 id="5-walkthrough-1-15-min-if-not-done-in-a-studio" tabindex="-1">5. Walkthrough 1 (15 min, if not done in a studio) <a class="header-anchor" href="#5-walkthrough-1-15-min-if-not-done-in-a-studio" aria-label="Permalink to &quot;5. Walkthrough 1 (15 min, if not done in a studio)&quot;">​</a></h3><p>Book an office-hours slot this week. Before you go, read <a href="./../../assessment/oral-walkthroughs.html#what-to-expect">What to expect</a>, commit everything, and practice explaining your save and load lines and your hand-written function.</p><h3 id="6-update-specmd-and-promptsmd-30-min" tabindex="-1">6. Update SPEC.md and PROMPTS.md (30 min) <a class="header-anchor" href="#6-update-specmd-and-promptsmd-30-min" aria-label="Permalink to &quot;6. Update SPEC.md and PROMPTS.md (30 min)&quot;">​</a></h3><ul><li><code>SPEC.md</code>: the criterion for your hand-written function is there, every criterion matches the finished tool, and &quot;Last updated&quot; has today&#39;s date.</li><li><code>PROMPTS.md</code> covers weeks 5–8: your Goldfish test, key prompts, what the AI got wrong and how you noticed, checks written first, teach-backs, the function you wrote by hand (its check, the review, what you accepted), and <strong>What I wrote or decided myself</strong>.</li></ul><h3 id="7-reflection-on-canvas-30-min" tabindex="-1">7. Reflection on Canvas (30 min) <a class="header-anchor" href="#7-reflection-on-canvas-30-min" aria-label="Permalink to &quot;7. Reflection on Canvas (30 min)&quot;">​</a></h3><p>Use the four headings of the <a href="./../../templates/REFLECTION.html">reflection template</a>, on Canvas. Anchor it in a concrete moment: a line you wrote by hand, the moment a test turned red when you broke the code, a question in your walkthrough. Then answer in two or three sentences: which part of your Project 1 could you explain least well this week, and what will you do about it?</p><blockquote><p>🔴 <strong>AI off.</strong> 150–300 words, graded on specifics, not polish (<a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">reflection rubric</a>). It goes on Canvas, not in your repository.</p></blockquote><h3 id="8-mid-course-survey-10-min" tabindex="-1">8. Mid-course survey (10 min) <a class="header-anchor" href="#8-mid-course-survey-10-min" aria-label="Permalink to &quot;8. Mid-course survey (10 min)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> Fill in the anonymous mid-course survey your instructor shares on Canvas. It asks what&#39;s working, what isn&#39;t, and how confident you feel explaining your own code. You&#39;re halfway through the course: honest answers change the second half. Self-paced learners: answer the same three questions at the end of your reflection.</p><hr><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> Project 1 is live, and <code>npm test</code> runs at least three passing tests of your own logic. Week 9 starts from a Node project with tests.</p><p><strong>Fallen behind?</strong> Tell your instructor early. A <a href="./../../assessment/#late-work-and-grace-tokens">grace token</a> can buy you time on Project 1, and you can practice the testing steps on the <a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">rescue starter</a> before week 9.</p></div><hr><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><h3 id="a-test-a-second-module" tabindex="-1">A. Test a second module <a class="header-anchor" href="#a-test-a-second-module" aria-label="Permalink to &quot;A. Test a second module&quot;">​</a></h3><p>Move another calculation (a total, a streak, a sort) into its own file in <code>lib/</code>, with at least two tests written first, one of them an edge case.</p><h3 id="b-catch-the-clinics-bug-3-with-a-test" tabindex="-1">B. Catch the clinic&#39;s bug 3 with a test <a class="header-anchor" href="#b-catch-the-clinics-bug-3-with-a-test" aria-label="Permalink to &quot;B. Catch the clinic&#39;s bug 3 with a test&quot;">​</a></h3><p>In the clinic, <code>40 + &quot;5&quot;</code> became <code>&quot;405&quot;</code>. Write a test for a pure <code>addPages(pagesRead, typed)</code> that fails if the typed text isn&#39;t converted, then make it pass. What should it do with <code>&quot;abc&quot;</code> or <code>&quot;-5&quot;</code>? Test those too.</p><h3 id="c-get-ahead-on-week-9" tabindex="-1">C. Get ahead on week 9 <a class="header-anchor" href="#c-get-ahead-on-week-9" aria-label="Permalink to &quot;C. Get ahead on week 9&quot;">​</a></h3><p>Skim the <a href="./../../resources/web-basics.html">How the Web Works</a> sections on requests, APIs and the trust boundary.</p>',44)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
